function attachEntity(T, face, cells, X) {
  let targets = cells;
  if (T.every) { const k = (c) => (X.roof ? c.u + c.v : c.u), k0 = Math.min(...cells.map(k)); targets = cells.filter((c) => (k(c) - k0) % T.every === 0); }
  const facing = OUTDIR(X), dataVersion = X.grid.dataVersion ?? 4189;
  for (const c of targets) {
    const p = X.roof ? [c.p[0], c.p[1] + 1, c.p[2]] : add(c.p, X.out);
    let block, state, nbt;
    if (T.banner) {
      const [color = "white", ...rest] = T.banner, pats = [];
      for (let k = 0; k + 1 < rest.length; k += 2) pats.push({ pattern: rest[k], color: rest[k + 1] });
      block = X.roof ? `${color}_banner` : `${color}_wall_banner`; state = X.roof ? { rotation: "0" } : { facing };
      nbt = tg.compound({ id: tg.string("minecraft:banner"), patterns: tg.list("compound", pats.map((q) => ({ pattern: tg.string(`minecraft:${q.pattern}`), color: tg.string(q.color) }))) });
    } else {
      const wood = T.wood || "oak", lines = (T.text || "").split(/\s*\|\s*|\\n/).flatMap((l) => (l.length > 15 ? l.match(/.{1,15}(\s|$)/g).map((x) => x.trim()) : [l])).slice(0, 4);
      block = X.roof ? `${wood}_sign` : `${wood}_wall_sign`; state = X.roof ? { rotation: "0", waterlogged: "false" } : { facing, waterlogged: "false" };
      const msg = (s) => (dataVersion >= 4325 ? String(s ?? "") : JSON.stringify({ text: String(s ?? "") }));
      const side = (ls) => ({ messages: tg.list("string", [0, 1, 2, 3].map((i) => msg(ls[i]))), color: tg.string("black"), has_glowing_text: tg.byte(0) });
      nbt = tg.compound({ id: tg.string("minecraft:sign"), is_waxed: tg.byte(0), front_text: tg.compound(side(lines)), back_text: tg.compound(side([])) });
    }
    X.put(p, { ...X.mk(block, {}), state, nbt }, RAIL);
  }
