1	// Part 5, Shopfronts (six Folio businesses, both faces): fascia names, piers with log-end panels, awnings in each
2	// business's wood, and hanging signs on the piers (plan FACADES, item 4 of the parts). Every helper writes only into air,
3	// so the socket boxes, wall lines and clear zones stay untouched. North = z 5 (fascia), south = z 32 (mirror of 5).
4	import { fasciaBoard, pierPanel, awning, hangSign } from "../vocab.mjs";
5	
6	// the palette lists four banner dyes (white, black, brown, orange) and wall hanging signs, not every dye or wall sign the
7	// vocabulary writes: a banner in a dye off the list takes the nearest listed one, a wall sign becomes the hanging sign of its wood
8	const BANNER_DYE = { light_gray: "white", red: "brown" };
9	
10	const withNbt = (nbt, key, value) => nbt && { ...nbt, value: { ...nbt.value, [key]: value } };
11	
12	// the block a vocabulary write lands as, and its block entity (sign text, banner patterns) to match
13	function paletteBlock(block, state, nbt) {
14	  const sign = /^((?:minecraft:)?)(\w+)_wall_sign$/.exec(block);
